import{_ as a,H as e,f as n,i}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"20 | OPA：为Kubernetes生态系统构建安全堡垒","description":"","frontmatter":{},"headers":[{"level":2,"title":"Kubernetes 安全性：从 PSP 到 OPA 的转变","slug":"kubernetes-安全性-从-psp-到-opa-的转变","link":"#kubernetes-安全性-从-psp-到-opa-的转变","children":[]},{"level":2,"title":"如何理解 OPA？","slug":"如何理解-opa","link":"#如何理解-opa","children":[]},{"level":2,"title":"OPA 的三大优势","slug":"opa-的三大优势","link":"#opa-的三大优势","children":[]},{"level":2,"title":"Gatekeeper 的配置和使用","slug":"gatekeeper-的配置和使用","link":"#gatekeeper-的配置和使用","children":[]},{"level":2,"title":"案例：禁止用户使用 gp3 类型的 Storage Class","slug":"案例-禁止用户使用-gp3-类型的-storage-class","link":"#案例-禁止用户使用-gp3-类型的-storage-class","children":[]},{"level":2,"title":"OPA 的缺点","slug":"opa-的缺点","link":"#opa-的缺点","children":[]},{"level":2,"title":"CEL 的发展计划和前景","slug":"cel-的发展计划和前景","link":"#cel-的发展计划和前景","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"云原生基础架构实战课/20｜OPA：为Kubernetes生态系统构建安全堡垒.md","filePath":"云原生基础架构实战课/20｜OPA：为Kubernetes生态系统构建安全堡垒.md","lastUpdated":1795537597000}'),p={name:"云原生基础架构实战课/20｜OPA：为Kubernetes生态系统构建安全堡垒.md"};function t(l,s,r,h,o,k){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_20-opa-为kubernetes生态系统构建安全堡垒" tabindex="-1">20 | OPA：为Kubernetes生态系统构建安全堡垒 <a class="header-anchor" href="#_20-opa-为kubernetes生态系统构建安全堡垒" aria-label="Permalink to &quot;20 | OPA：为Kubernetes生态系统构建安全堡垒&quot;">​</a></h1><p>你好，我是潘野。</p><p>前面的课程里，我们着重讲解了云原生中的加密管理的方法与实现手段。</p><p>而在现代云原生生态系统中，Kubernetes 已成为容器编排的事实标准。但随着 Kubernetes 集群的规模和复杂性增加，其集群本身安全性管理也面临着越来越多的挑战。原来的安全策略已经逐渐跟不上新的形势，特别是在灵活性和细粒度控制方面。</p><p>今天我们将通过一个具体场景来探讨 Kubernetes 安全策略的不足，学习如何通过开放策略代理（OPA）弥补这些不足，并带你展望未来 Kubernetes 中条件表达式语言（CEL）的发展计划。</p><h2 id="kubernetes-安全性-从-psp-到-opa-的转变" tabindex="-1">Kubernetes 安全性：从 PSP 到 OPA 的转变 <a class="header-anchor" href="#kubernetes-安全性-从-psp-到-opa-的转变" aria-label="Permalink to &quot;Kubernetes 安全性：从 PSP 到 OPA 的转变&quot;">​</a></h2><p>我们先来看一个场景。</p><p>公司里运行着几个多租户 Kubernetes 集群，其中包括金融、零售、支付等等多个业务的应用程序，这些业务对安全性和数据隔离有着严格的要求。一般情况下，我们会将不同业务的程序放在不同的 namespace 中，配合 Kubernetes 的原生 Role-Based Access Control (RBAC) 来管理访问控制，但是这并不够用。</p><p>比如说，业务 A 在 deployment 中定义了使用 privilege 的权限，这个 deployment 启动之后的容器就有能力看到宿主机上的整个磁盘目录，这就增加了其他业务被攻击的风险。</p><p>所以 Kubernetes 中设立了一个安全机制，叫做 Pod Security Policies (PSP)。这是一种集群级别的安全机制，用于控制 Pod 的安全规范。PSP 旨在为 Pod 运行时提供安全保障，通过定义一系列条件来限制 Pod 可以使用的资源和权限。</p><p>PSP 可以做哪些安全策略呢？主要有如下几个方面。</p><ol><li><p>限制容器是否可以运行在特权模式下。</p></li><li><p>控制容器是否可以挂载文件系统，以及挂载的类型。</p></li><li><p>限制容器使用的网络模式，例如禁用 hostNetwork，从而防止容器访问主机网络。</p></li><li><p>指定 Pod 中容器运行的用户和用户组。这可以防止容器以 root 用户运行，增加安全性。</p></li></ol><p>PSP 提供了一系列强大的安全功能，但在实际使用中也暴露出一些明显的不足，最大的不足是它只能控制 pod，缺乏更细粒度的控制。比如不能基于单个用户或具体应用的差异化来配置安全策略，也不能控制其他的资源。</p><p>所以从 Kubernetes 1.21 版本开始，PSP 被标记为弃用，并在 1.25 版本中被移除。这迫使我们寻找其他的安全替代方案，那么此时社区推荐的方案是开放策略代理（Open PolicyAgent，后面我们简称 OPA）。</p><h2 id="如何理解-opa" tabindex="-1">如何理解 OPA？ <a class="header-anchor" href="#如何理解-opa" aria-label="Permalink to &quot;如何理解 OPA？&quot;">​</a></h2><p>你从网络上搜索到的关于 OPA 的介绍，大多都是这样的。</p><ul><li>开放策略代理（Open Policy Agent）是一个开源的、通用的策略引擎，OPA 通过提供一个高级的策略语言—Rego（用于表达策略和查询数据）—让开发人员能够定义和执行跨微服务、Kubernetes、CI/CD 管道、API 网关等策略。</li></ul><p>看到这个介绍，恐怕你会越看越迷惑。让我换个方式带你理解就会容易很多。通俗来说，OPA就像框架一样，提供了接口、语法工具等，而具体的策略逻辑和需求，则需要你自己根据自己的应用场景来实现。</p><p>所以我们要将 OPA 的功能扩展到 Kubernetes 环境中，还需要一个真正的软件实现，这里就是 OPA 的Gatekeeper。</p><p>Gatekeeper 是专为强化 Kubernetes 的安全性而设计的。它通过实施自定义策略来控制和管理对 Kubernetes API 的访问。有了 Gatekeeper， Kubernetes 管理员就可以定义细粒度的、声明式的策略。这些策略在资源创建或更新时自动执行，保证集群状态符合组织的合规性和安全标准。</p><h2 id="opa-的三大优势" tabindex="-1">OPA 的三大优势 <a class="header-anchor" href="#opa-的三大优势" aria-label="Permalink to &quot;OPA 的三大优势&quot;">​</a></h2><p>那么具体来说，OPA 究竟在哪几个方面比 PSP 表现更好呢？主要是三个方面，我们依次看看。</p><p>第一，支持细粒度控制。OPA 的 Rego 语法允许用户编写非常细粒度和复杂的逻辑，不仅限于安全设置，还可以涵盖访问控制、数据过滤等多种用途。不仅可以对 Pod 进行管理，也可以对其他资源进行管理。</p><p>第二，支持动态策略更新。OPA 支持动态策略加载和更新，不需要重启服务或组件。这让管理大规模环境中的策略变得更加灵活和高效。</p><p>举个例子，如果我们想阻止非认证的容器镜像部署，以往的做法是在 APIServer 的 AdmissionWebhook 中做拦截。但是这一步在首次部署的时候，需要更改 APIServer 配置并重启APIServer，这会带来一定的风险。而使用 OPA 的方式，无需重启 APIServer，配置即刻生效，这样就避免了繁琐操作。</p><p>第三是支持审计和追踪功能。Gatekeeper 会定期扫描 Kubernetes 集群中的所有资源，以验证它们是否符合所有激活的策略（Constraints）。我们也可以通过 Pub/Sub 模式导出审计结果。</p><h2 id="gatekeeper-的配置和使用" tabindex="-1">Gatekeeper 的配置和使用 <a class="header-anchor" href="#gatekeeper-的配置和使用" aria-label="Permalink to &quot;Gatekeeper 的配置和使用&quot;">​</a></h2><p>前面我们了解了 OPA 和 Gatekeeper 的各种优势，那我们怎么使用它们来防护集群呢？</p><p>首先，我们需要安装 Gatekeeper，直接运行下面这条命令即可，等待所有的 pod 都完成启动。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/open-policy-agent/gatekeeper/v</span></span></code></pre></div><p>也可以使用 helm 的模式安装，命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>helm repo add gatekeeper https://open-policy-agent.github.io/gatekeeper/charts</span></span>
<span class="line"><span>helm install gatekeeper/gatekeeper --name-template=gatekeeper --namespace gatekee</span></span></code></pre></div><p>Gatekeeper 有两个重要的基本概念需要你关注。</p><p>第一个概念是 ConstraintTemplates，它定义了可以在集群中实施的策略类型。</p><p>一个 ConstraintTemplate 主要包含以下几个部分。</p><ul><li><p>CRD 规范：定义了将由该模板创建的 CRD 的结构，包括其名称和属性。</p></li><li><p>Targets：指定该模板将应用于哪些 Kubernetes API 对象（如 Pod、Service 等）。</p></li><li><p>Rego Policies：使用 Rego 语言编写的实际策略逻辑，定义了资源必须满足的条件。</p></li></ul><p>第二个概念是 Constraints。Constraints 是实际应用于集群资源的对象，这些对象基于ConstraintTemplates 来定义。ConstraintTemplates 提供了策略的模板，而 Constraints 则是这些策略的具体实现，指定了策略应用的具体条件和目标。</p><p>那么接下来我们就结合一个案例，看看如何写出一些用于集群防护的策略。</p><h2 id="案例-禁止用户使用-gp3-类型的-storage-class" tabindex="-1">案例：禁止用户使用 gp3 类型的 Storage Class <a class="header-anchor" href="#案例-禁止用户使用-gp3-类型的-storage-class" aria-label="Permalink to &quot;案例：禁止用户使用 gp3 类型的 Storage Class&quot;">​</a></h2><p>首先，我们创建一个 ConstraintTemplates。</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">apiVersion: templates.gatekeeper.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind: ConstraintTemplate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">metadata:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> annotations:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   description: Denied creation of PVCs backed by Rook.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> name: denygp3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spec:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crd:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   spec:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     names:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">       kind: DenyGP3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     validation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">       legacySchema: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> targets:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rego: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">     package</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gp3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     violation[{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;msg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: msg}] {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">       sc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> input.review.object.spec.storageClassName</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">       contains</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sc, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gp3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">       msg </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;gp3 persistent volumes are not allowed.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   target: admission.k8s.gatekeeper.sh</span></span></code></pre></div><p>对照上面讲的 ConstraintTemplates 的几个部分，我们简单了解一下这个配置的重点。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首先是 CRD 规范，这里我们定义了一个叫做 DenyGP3 的 API 资源。然后在 Targets 中，用</span></span></code></pre></div><p>rego 的语法写了一段规则。在这个规则下如果提交的 PVC spec 中的 storageClassName 包含 gp3，命令行就会弹出“gp3 persistent volumes are not allowed”这一提示。</p><p>接下来我们需要创建 Constraints。</p><p>Constraints 的作用是指定策略应用的具体条件和目标，这里应用的目标是配置文件最后一行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>的 PersistentVolumeClaim，而作用的条件参数是 enforcementAction ，它这里的值是</span></span>
<span class="line"><span>deny，也就是发现匹配了 DenyGP3 规则的请求，默认会拒绝；但如果请求是 kube-system</span></span></code></pre></div><p>中的，则放行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>items:</span></span>
<span class="line"><span>- apiVersion: constraints.gatekeeper.sh/v1beta1</span></span>
<span class="line"><span> kind: DenyGP3</span></span>
<span class="line"><span> metadata:</span></span>
<span class="line"><span>   name: deny-gp3</span></span>
<span class="line"><span> spec:</span></span>
<span class="line"><span>   enforcementAction: deny</span></span>
<span class="line"><span>   match:</span></span>
<span class="line"><span>     excludedNamespaces:</span></span>
<span class="line"><span>     - kube-system</span></span>
<span class="line"><span>     kinds:</span></span>
<span class="line"><span>     - apiGroups:</span></span>
<span class="line"><span>       - &quot;&quot;</span></span>
<span class="line"><span>       kinds:</span></span>
<span class="line"><span>       - PersistentVolumeClaim</span></span></code></pre></div><p>这样就定义了一个控制策略，我们来看看效果。</p><p>这里我们需要定义一个 PVC 的配置文件，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cat pvc.yaml</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: PersistentVolumeClaim</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: myclaim</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> accessModes:</span></span>
<span class="line"><span>   - ReadWriteOnce</span></span>
<span class="line"><span> volumeMode: Filesystem</span></span>
<span class="line"><span> resources:</span></span>
<span class="line"><span>   requests:</span></span>
<span class="line"><span>     storage: 8Gi</span></span>
<span class="line"><span> storageClassName: gp3</span></span></code></pre></div><p>然后 apply 下这个 PVC 配置，验证一下 OPA Gatekeeper 是否会阻拦这个请求。从输出结果</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你可以看到 Gatekeeper 阻拦了这个请求，并且抛出了 gp3 persistent volumes are</span></span>
<span class="line"><span>not allowed 的报错。</span></span>
<span class="line"><span># kubectl -n default create -f pvc.yaml</span></span>
<span class="line"><span>Error from server ([deny-gp3] gp3 persistent volumes are not allowed.): error whe</span></span></code></pre></div><p>前面我提到过，OPA 是一个开源且通用的策略引擎，适用于多种软件系统中的授权和策略决策。它支持为 Kubernetes、API 网关等提供控制策略。这里我再稍微提一下 OPA 的其他用途，比如，OPA 可以集成到 Envoy 代理中，实现细粒度的访问控制。</p><p>其基本原理是使用 Envoy 的 External Authorization filter 配置代理，以在请求处理流程中嵌入OPA 调用，OPA 中定义的策略策略可以基于请求的各种属性（如 HTTP 头、路径、方法等）进行细粒度控制。</p><h2 id="opa-的缺点" tabindex="-1">OPA 的缺点 <a class="header-anchor" href="#opa-的缺点" aria-label="Permalink to &quot;OPA 的缺点&quot;">​</a></h2><p>尽管 Open Policy Agent (OPA) 提供了强大的灵活性和广泛的适用性，它也存在一些潜在的挑战和限制。</p><p>首先，OPA 的学习曲线陡峭。前面我们了解到，OPA 使用 Rego 语言来定义策略。而 Rego是一种声明性语言，除了官方文档之外，可参考的资料不是很多。对于不熟悉声明性或逻辑编程范式的开发者来说，Rego 可能难以理解和掌握。</p><p>其次是性能问题。在高负载或复杂策略的情况下，OPA 可能会遇到性能瓶颈。由于每个请求都需要评估策略，这可能导致延迟增加，特别是在分布式系统中延迟会更为严重。所以我们需要从 rego 语法优化、请求量的预先评估，以及使用缓存减少对 OPA 服务的请求次数这几方面来综合解决，从而减少总体延迟。</p><p>最后还有一点，OPA Gatekeeper 用来控制 Kubernetes 集群的安全策略，OPA envoy 用来控制流量层的安全策略，两者功能比较类似，但是两者的配置却无法统一。这增加了我们学习和使用它的成本。</p><h2 id="cel-的发展计划和前景" tabindex="-1">CEL 的发展计划和前景 <a class="header-anchor" href="#cel-的发展计划和前景" aria-label="Permalink to &quot;CEL 的发展计划和前景&quot;">​</a></h2><p>前面说到 rego 的语法学习成本比较高，同时 OPA 属于外挂 controller，可能存在性能问题。Kubernetes 官方社区在决定废弃 PSP 之后，也看到了 OPA 的这些不足，并致力于设计下一代的安全控制策略，这就是我们接下来要讲的 CEL。</p><p>CEL（Common Expression Language）是一种轻量级的表达式语言，旨在简化数据查询和操作，以此应对越来越复杂的安全需求。Kubernetes 社区正在探索将 CEL 集成到不同的Kubernetes 组件中，以提供更灵活的配置和策略决策能力。</p><p>CEL 可用于以下场景：</p><ol><li><p>Admission Control：Kubernetes 的 Admission Controllers 负责在对象创建或更新时执行策略检查。通过使用 CEL，管理员可以编写更复杂的入场条件或验证逻辑，而无需编写和维护复杂的 Webhook 服务。</p></li><li><p>Custom Resource Definitions (CRDs)：在 CRDs 中，CEL 可用于定义更复杂的验证规则，这些规则超出了标准的基于类型的验证。</p></li><li><p>API Gateway：在 API 网关中，CEL 可用于定义复杂的路由规则，如基于请求内容的动态路由决策。</p></li></ol><p>我们来看一个例子，我们定义了一个校验规则，当创建（create）或者修改（update）deployment 的时候，spec 中的 replicas 这个值需要大于等于 3。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">apiVersion: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">admissionregistration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">k8s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">io/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v1alpha1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind: ValidatingAdmissionPolicy</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">metadata:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deploy-replicas-policy&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spec:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> matchConstraints:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   resourceRules:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apiGroups:   [&quot;apps&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     apiVersions: [&quot;v1&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     operations:  [&quot;CREATE&quot;, &quot;UPDATE&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     resources:   [&quot;deployments&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> validations:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> expression: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;object.spec.replicas &gt;= 3&quot;</span></span></code></pre></div><p>比较一下，用 CEL 编写这样的一个规则，是不是比 OPA Gatekeeper 更为简洁明了？</p><p>虽然 CEL 在 Kubernetes 中的应用还在开发阶段，但它的引入预示着更灵活和强大的策略定义方式。相信随着时间的推移，CEL 将在 Kubernetes 生态系统中扮演越来越重要的角色。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>我们今天深入探讨了云原生环境中，特别是在 Kubernetes 生态系统中安全管理的演变和挑战。</p><p>通过回顾传统的安全策略，如 Kubernetes 的 Role-Based Access Control (RBAC) 和 PodSecurity Policies (PSP)，我们发现它们在应对现代化多租户集群环境中的局限性，特别是在灵活性和细粒度控制方面。</p><p>正是为了解决这样的问题，开放策略代理（OPA）应运而生，随之而来的还有 OPA 在Kubernetes 中的实现——Gatekeeper。OPA 通过其策略语言 Rego 提供了一种灵活、细粒度的安全策略定义方式，使得管理员可以更精确地控制和管理集群资源。</p><p>相比于 PSP，OPA 支持更复杂的逻辑、动态策略更新以及细粒度的控制，虽然它也带来了一定的学习曲线和潜在的性能挑战，但优势依然很明显。</p><p>另外，我们了解了 Kubernetes 社区正在研究的下一代安全策略工具——条件表达式语言（CEL）。CEL 旨在提供一种更简洁、更强大的方式来表达策略和规则，预计它将进一步简化策略的定义并提高执行效率。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请你用 Gatekeeper 定义一个策略，规则是容器启动的时候禁止使用 host network。</p><p>欢迎在评论区与我讨论。如果这一讲对你有启发，也欢迎分享给身边更多朋友。</p>`,79)])])}const g=a(p,[["render",t]]);export{d as __pageData,g as default};
